"""Betti staircase of the prime cloud: components vs. resolution."""
from __future__ import annotations
from math import isqrt
from typing import List

def is_prime(m: int) -> bool:
    if m < 2: return False
    if m < 4: return True
    if m % 2 == 0: return False
    return all(m % d for d in range(3, isqrt(m) + 1, 2))

def first_primes(n: int) -> List[int]:
    ps, c = [], 2
    while len(ps) < n:
        if is_prime(c): ps.append(c)
        c += 1
    return ps

def prime_gaps(ps: List[int]) -> List[int]:
    return [ps[i+1] - ps[i] for i in range(len(ps) - 1)]

def betti_zero(gaps: List[int], eps: float) -> int:
    return 1 + sum(1 for g in gaps if g > eps)

if __name__ == "__main__":
    gaps = prime_gaps(first_primes(50))
    for eps in range(0, 12):
        b = betti_zero(gaps, eps)
        print(f"eps={eps:>2}  beta_0={b:>2}  " + "#" * b)

"""Betti curve divergence: beta_0(eps, n) grows without bound in n."""
from __future__ import annotations
from math import isqrt
from typing import List

def is_prime(m: int) -> bool:
    if m < 2: return False
    if m < 4: return True
    if m % 2 == 0: return False
    return all(m % d for d in range(3, isqrt(m) + 1, 2))

def first_primes(n: int) -> List[int]:
    ps, c = [], 2
    while len(ps) < n:
        if is_prime(c): ps.append(c)
        c += 1
    return ps

def betti_curve(n_values: List[int], eps: float) -> List[int]:
    ps = first_primes(max(n_values))
    gaps = [ps[i+1] - ps[i] for i in range(len(ps) - 1)]
    return [1 + sum(1 for g in gaps[:n] if g > eps) for n in n_values]

if __name__ == "__main__":
    ns = [10, 100, 1000, 5000, 20000]
    for eps in (2, 6, 14, 20):
        print(f"eps={eps:>2}: " + str(list(zip(ns, betti_curve(ns, eps)))))

